  modal.innerHTML = '<div class="lobby-browser" id="lobbyBrowser" role="dialog" aria-modal="true" aria-labelledby="lobbyBrowserTitle"><div class="lobby-browser-head"><div><span class="main-menu-kicker">SERVIDORES ONLINE</span><h2 id="lobbyBrowserTitle">Lista de servidores</h2><p class="lobby-browser-subtitle">Escolha uma sala e veja quantos jogadores ainda podem entrar.</p></div><button type="button" class="lobby-browser-close" id="closeLobbyBrowserBtn">Fechar</button></div><div class="server-toolbar"><span class="server-count" id="serverCount">0 servidores encontrados</span><span>Limite m\u00e1ximo: 20 jogadores</span></div><div class="lobby-list" id="availableLobbies"></div><button type="button" class="lobby-create-btn" id="newLobbyBtn">+ Criar servidor</button><div class="lobby-create-panel" id="lobbyCreatePanel"><label for="lobbyNameInput">Nome do servidor</label><div class="lobby-create-fields"><input id="lobbyNameInput" type="text" maxlength="28" value="Partida amistosa" placeholder="Ex.: Copa de domingo"><div><label for="lobbyLimitInput">Limite de jogadores</label><input id="lobbyLimitInput" type="number" min="2" max="20" value="10"></div></div><div class="lobby-create-actions"><button type="button" class="lobby-create-cancel" id="cancelLobbyCreateBtn">Cancelar</button><button type="button" class="lobby-create-submit" id="confirmLobbyCreateBtn">Criar servidor</button></div></div><div class="lobby-created" id="createdLobby"><span>Servidor criado. Compartilhe o c\u00f3digo:</span><strong id="lobbyCode">------</strong><button type="button" id="copyLobbyBtn">Copiar c\u00f3digo</button></div></div>';
  const searchBar = document.createElement('div'); searchBar.className = 'lobby-search'; searchBar.innerHTML = '<input id="lobbySearchInput" type="search" maxlength="6" placeholder="Buscar pelo c\u00f3digo do lobby"><button type="button" id="searchLobbyBtn">Buscar</button>'; $('availableLobbies').before(searchBar);
  const visibilityField = document.createElement('div'); visibilityField.innerHTML = '<label for="lobbyVisibilityInput">Visibilidade</label><select id="lobbyVisibilityInput"><option value="public">P\u00fablico</option><option value="private">Privado</option></select>'; $('lobbyLimitInput').parentElement.after(visibilityField);
