  const storageKey = 'simuladorfut:available-lobbies';
  const apiBase = window.location.protocol === 'file:' ? 'http://localhost:3010' : '';
  const syncFromServer = async () => { try { const response = await fetch(`${apiBase}/api/lobbies`); if (!response.ok) return false; const data = await response.json(); saveLobbies(data.lobbies || []); return true; } catch { return false; } };
  const serverRequest = async (url, options) => { try { const response = await fetch(`${apiBase}${url}`, { headers: { 'Content-Type': 'application/json' }, ...options }); const data = await response.json(); return response.ok ? data : null; } catch { return null; } };
  const readLobbies = () => { try { const parsed = JSON.parse(localStorage.getItem(storageKey) || '[]'); return parsed.filter(item => item && item.code && Date.now() - Number(item.createdAt || 0) < 7200000).map(item => ({ ...item, name: item.name || 'Partida amistosa', visibility: item.visibility === 'private' ? 'private' : 'public', password: item.password || '', maxPlayers: Math.max(2, Math.min(20, Number(item.maxPlayers) || 10)), players: Math.max(1, Math.min(Number(item.maxPlayers) || 10, Number(item.players) || 1)) })); } catch { return []; } };
  const saveLobbies = list => { try { localStorage.setItem(storageKey, JSON.stringify(list)); } catch {} };
  const refreshStyle = document.createElement('style'); refreshStyle.textContent = '.server-refresh{border:0;border-radius:8px;padding:7px 10px;background:#edf3ee;color:var(--green-dark);font:700 11px DM Sans,sans-serif;cursor:pointer}.server-refresh:disabled{opacity:.6;cursor:wait}'; document.head.appendChild(refreshStyle);
  const refreshButton = document.createElement('button'); refreshButton.type = 'button'; refreshButton.className = 'server-refresh'; refreshButton.id = 'refreshLobbiesBtn'; refreshButton.textContent = '↻ Atualizar'; document.querySelector('.server-toolbar').appendChild(refreshButton);
  refreshButton.addEventListener('click', async () => { refreshButton.disabled = true; refreshButton.textContent = 'Atualizando...'; await syncFromServer(); renderLobbies($('lobbySearchInput').value); refreshButton.disabled = false; refreshButton.textContent = '↻ Atualizar'; });
  const renderLobbies = (search = '') => { const container = $('availableLobbies'); if (!container) return; const term = search.trim().toUpperCase(); const allLobbies = readLobbies(); const lobbies = term ? allLobbies.filter(item => item.code.toUpperCase().includes(term)) : allLobbies; saveLobbies(allLobbies); $('serverCount').textContent = `${lobbies.length} servidor${lobbies.length === 1 ? '' : 'es'} encontrado${lobbies.length === 1 ? '' : 's'}`; container.innerHTML = ''; if (!lobbies.length) { container.innerHTML = term ? '<div class="lobby-list-empty">Nenhum lobby encontrado com esse c\u00f3digo.</div>' : '<div class="lobby-list-empty">Nenhum servidor aberto no momento.<br>Crie o primeiro servidor para jogar online.</div>'; return; } lobbies.forEach(item => { const row = document.createElement('div'); row.className = 'available-lobby'; const info = document.createElement('div'); info.innerHTML = `<span class="available-lobby-name">${item.name}</span><span class="available-lobby-code">${item.code}</span><span class="available-lobby-meta">${item.visibility === 'private' ? 'Servidor privado · senha necess\u00e1ria' : 'Servidor p\u00fablico'}</span>`; const players = document.createElement('div'); players.className = 'server-players'; players.innerHTML = `${item.players}/${item.maxPlayers}<small>jogadores</small>`; const status = document.createElement('div'); status.className = 'server-status'; status.textContent = item.players >= item.maxPlayers ? 'Cheio' : 'Aberto'; const join = document.createElement('button'); join.type = 'button'; join.textContent = item.players >= item.maxPlayers ? 'Cheio' : 'Entrar'; join.disabled = item.players >= item.maxPlayers; join.addEventListener('click', () => { if (item.visibility === 'private' && prompt('Digite a senha do lobby:') !== item.password) { alert('Senha incorreta.'); return; } const updated = readLobbies().map(server => server.code === item.code ? { ...server, players: Math.min(server.maxPlayers, server.players + 1) } : server); saveLobbies(updated); renderLobbies(term); }); row.append(info, players, status, join); container.appendChild(row); }); };
  const makeCode = () => { const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'; return Array.from({ length: 6 }, () => chars[randomIndex(chars.length)]).join(''); };
