  $('lobbyVisibilityInput').addEventListener('change', event => { $('lobbyPasswordField').style.display = event.target.value === 'private' ? 'block' : 'none'; });
   $('confirmLobbyCreateBtn').addEventListener('click', async () => { const maxPlayers = Math.max(2, Math.min(20, Number($('lobbyLimitInput').value) || 10)); const name = $('lobbyNameInput').value.trim() || 'Partida amistosa'; const visibility = $('lobbyVisibilityInput').value; const password = $('lobbyPasswordInput').value.trim(); if (visibility === 'private' && !password) { alert('Defina uma senha para o lobby privado.'); $('lobbyPasswordInput').focus(); return; } const created = await serverRequest('/api/lobbies', { method: 'POST', body: JSON.stringify({ name, visibility, password, maxPlayers }) }); if (created) { await syncFromServer(); modal.classList.remove('is-open'); openOnlineLobbyRoom(created.lobby.code, 'owner', created.lobby, password); return; } alert('Servidor online indisponível. Inicie npm start para criar uma sala online.'); });
